	const request = operations.templates.listAll.effect(execution);
	return request.pipe(
		Effect.tap((catalog) =>
			Effect.suspend(() => {
				if (generation !== currentGeneration) return Effect.void;
				hasLoadedValueForExecution(catalog);
				return Cache.set(
					cache,
					EXERCISE_TEMPLATE_CATALOG_CACHE_KEY,
					catalog,
				);
			}),
		),
	);
}

function hasLoadedValueForExecution(
	_catalog: readonly ExerciseTemplate[],
): void {
	// Kept as a separate synchronous hook so the lookup remains an Effect
	// program. The catalog's enclosing effect marks successful values.
