import { InMemoryTransport, McpServer } from "@modelcontextprotocol/server";
import {
	Client,
	type JSONObject,
	type JSONValue,
} from "@modelcontextprotocol/client";
import nock from "nock";
import {
	afterAll,
	afterEach,
	beforeAll,
	beforeEach,
	describe,
	expect,
	it,
	vi,
} from "vitest";
import { registerHevyResources } from "../../../packages/core/src/resources/hevy.js";
